import{_ as e,c as o,o as d,ae as n}from"./chunks/framework.CFeneB-q.js";const h=JSON.parse('{"title":"移动端 · 技术栈","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/technology-stack.md","filePath":"mobile/technology-stack.md","lastUpdated":1789438865000}'),i={name:"mobile/technology-stack.md"};function r(a,t,s,c,l,u){return d(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="移动端-·-技术栈" tabindex="-1">移动端 · 技术栈 <a class="header-anchor" href="#移动端-·-技术栈" aria-label="Permalink to &quot;移动端 · 技术栈&quot;">​</a></h1><blockquote><p>版本信息源自 <code>delivery-template-uniapp</code> 实际工程文件（manifest.json / package.json / uni_modules），2026-09-16 核对。<strong>如实记录现状，不按目标态虚构。</strong></p></blockquote><h2 id="版本矩阵" tabindex="-1">版本矩阵 <a class="header-anchor" href="#版本矩阵" aria-label="Permalink to &quot;版本矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>选型</th><th>版本</th><th>用途 / 说明</th></tr></thead><tbody><tr><td>框架</td><td>uni-app（<strong>Vue 2</strong>）</td><td><code>manifest.vueVersion: &quot;2&quot;</code>（compilerVersion 3）</td><td>一码多端：微信小程序 + App（Android）</td></tr><tr><td>工具链</td><td>HBuilderX</td><td>实际使用 <code>5.07.2026041006</code></td><td>HBuilderX 工程（<strong>非 CLI</strong>），运行/打包都在 IDE 内完成</td></tr><tr><td>UI 库</td><td>uView 2（<strong>本地迁移版</strong>）</td><td><code>uni_modules/uview-ui</code> v2.0.38</td><td>经「全局加载 → 局部加载」迁移改造，升级前必读迁移文档</td></tr><tr><td>上传组件</td><td>xe-upload</td><td><code>uni_modules/xe-upload</code> v1.0.2</td><td>第三方上传组件</td></tr><tr><td>图表</td><td>ECharts（libs 离线包）</td><td>5.6.1（UMD 全量构建）</td><td><code>libs/echarts.min.js</code>，图表页经 qiun-data-charts 体系消费</td></tr><tr><td>日期</td><td>dayjs（libs 离线包）</td><td>≥1.10（UMD 未嵌版本号，按 timezone 插件可用性推断）</td><td><code>libs/dayjs.js</code> + <code>libs/timezone.js</code> + <code>libs/utc.js</code></td></tr><tr><td>i18n</td><td>自研 mixin 方案</td><td><code>utils/mixin.js</code>（initI18n / t）+ <code>locale/</code> 词典</td><td>见下方「i18n 特别说明」</td></tr><tr><td>请求</td><td>自研 <code>utils/request.js</code></td><td>—</td><td>基于 uni.request 封装，用法见<a href="./function-development.html">功能开发</a></td></tr><tr><td>CSS</td><td>sass</td><td><code>sassImplementationName: &quot;node-sass&quot;</code></td><td>manifest 指定 node-sass 实现</td></tr><tr><td>声明依赖</td><td>vue-i18n</td><td>^9.1.9</td><td><strong>已声明、全工程零引用</strong>（见下）</td></tr></tbody></table><h2 id="i18n-特别说明-如实记录" tabindex="-1">i18n 特别说明（如实记录） <a class="header-anchor" href="#i18n-特别说明-如实记录" aria-label="Permalink to &quot;i18n 特别说明（如实记录）&quot;">​</a></h2><ul><li><code>package.json</code> 声明了 <code>vue-i18n ^9.1.9</code>，但<strong>全工程无任何 import</strong>——实际生效的是 <code>utils/mixin.js</code> 的自研方案：<code>initI18n</code> 按 <code>uni.getStorageSync(&#39;lang&#39;)</code> 装载词典，<code>t(key)</code> 查表翻译（zh 态直接返回原文 key，en 态查 <code>locale/</code> 词典，缺词回退原 key 并 console 报错）；</li><li><code>locale/AppLang.js</code> 以<strong>中文原文为 key</strong> 聚合 zh / en 词典（zh.js 约 113 条 / en.js 约 127 条），由 <code>App.vue</code> onLaunch 调用装载；</li><li>与 PC 端 i18n 方案完全不同，跨端移植词条时不可直接照搬。</li></ul><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><ul><li><strong>HBuilderX</strong>：工程无 engines 强制；uView2 自身要求 <code>HBuilderX ^3.1.0</code>；README 离线打包 SDK 更新链显示当前实际使用 <strong>5.07</strong>（历史：4.7.6 首次离线打包 → 4.87 → 5.04 → 5.07）。<strong>注意：App 热更新 SDK 版本需与 HBuilderX 版本匹配</strong>（README 记载 2.3.10 版曾用 5.07 重打包解决 sdk 不匹配）；</li><li><strong>微信开发者工具</strong>：运行、调试小程序必需；</li><li><strong>Android 真机</strong>：调试 App 端需要；</li><li><code>package.json</code> 里的 <code>dev:mp-weixin</code> 是<strong>顶层键而非 scripts 脚本</strong>（现状缺陷），不能以 <code>pnpm dev:mp-weixin</code> 方式运行；常规开发统一走 HBuilderX 的运行菜单（<code>.hbuilderx/launch.json</code> 内置 app-android / app-ios / mp-weixin 四套配置）。</li></ul><h2 id="选型说明与约定" tabindex="-1">选型说明与约定 <a class="header-anchor" href="#选型说明与约定" aria-label="Permalink to &quot;选型说明与约定&quot;">​</a></h2><ol><li><strong>uni-app Vue 2 现状</strong>：<strong>Vue3 迁移未立项</strong>。不要按 Vue3 语法假设读代码，也不要在需求或文档中虚构 Vue3 写法；uni-app Vue2 生态收缩风险与迁移规划见缺口分析 §4.3（遗留项，不承诺时间表）。</li><li><strong>uView 本地迁移版</strong>：UI 库不是 npm 依赖，而是 <code>uni_modules/uview-ui</code> 本地副本，且做过「全局加载 → 局部加载」迁移（按分包手动引入组件）。升级 uView 前必读<a href="/E9-Front-Dev-Guide.io/mobile/references/uview-migration-summary.html">迁移总结</a>与<a href="/E9-Front-Dev-Guide.io/mobile/references/uview-migration-plan.html">迁移计划完整版</a>。</li><li><strong>libs 离线包策略</strong>：dayjs / echarts / timezone / utc 以本地文件引入而非 npm 安装，规避 HBuilderX 工程依赖管理弱的短板；升级需手动替换文件。</li><li><strong>pap-* 组件族</strong>：自研业务组件统一 <code>pap-</code> 前缀 + easycom 自动注册（规则 <code>&quot;^pap-(.*)&quot;: &quot;@/components/pap-$1/pap-$1.vue&quot;</code>），页面里无需 import。清单见<a href="./function-development.html#常用组件">功能开发</a>。</li><li><strong>统计关闭</strong>：<code>manifest.json</code> 的 <code>uniStatistics.enable: false</code>。</li></ol><hr><p><strong>负责人</strong>：E9 前端团队 ｜ <strong>最后验证日期</strong>：2026-09-16 ｜ <strong>对应蓝本项目</strong>：<code>delivery-template-uniapp</code></p>',12)])])}const m=e(i,[["render",r]]);export{h as __pageData,m as default};
